#define main gen_compress_generator_main
#include "gen_compress_golden.cpp"
#undef main

extern "C" {

// Encode one source buffer. The Rust side's `refpack::compress` grows its
// output Vec internally; here the destination is sized generously up front
// (the C API requires a caller-provided buffer) — noted in the budget doc.
long bench_refpack_encode(const uint8_t *source, size_t len, uint8_t *dest, size_t dest_cap)
{
        int plen = REF_encode(dest, source, (int)len, nullptr);
        (void)dest_cap;
        return plen > 0 ? (long)plen : 0;
}

// Decode one compressed buffer into `dest` (exactly `ulen` bytes, like the
// Rust bench's `vec![0u8; ulen]` + `decode`).
long bench_refpack_decode(const uint8_t *packed, size_t packed_len, uint8_t *dest, size_t ulen)
{
        (void)packed_len;
        (void)ulen;
        int consumed = 0;
        int out = REF_decode(dest, packed, &consumed);
        return out > 0 ? (long)out : 0;
}

// REF_size over a packed buffer (part of the header-dispatch path).
int bench_refpack_ref_size(const uint8_t *packed)
{
        return REF_size(packed);
}

} // extern "C"
